    if not isinstance(data, dict):
        raise ValueError("input must be object")

    today = data.get("today")
    if not isinstance(today, str) or not today.strip():
        raise ValueError("today required")
    try:
        start = _dt.date.fromisoformat(today)
    except ValueError as exc:
        raise ValueError("invalid today") from exc

    # Monday is the first day of the week. Find the next natural week's Friday.
    # Weekday: Monday=0 ... Sunday=6.
    weekday = start.weekday()
    # Days until the coming Friday (inclusive of today if today is Friday).
    if weekday <= 4:  # Mon..Fri
        days_to_friday = 4 - weekday
    else:  # Sat, Sun -> next week's Friday
        days_to_friday = (7 - weekday) + 4
    end = start + _dt.timedelta(days=days_to_friday)

    dates = []
    cur = start
    while cur <= end:
        dates.append(cur.isoformat())
        cur += _dt.timedelta(days=1)

    return {"name": contract["name"], "result": {"dates": dates}}

