import json
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent


def _load_contract(path):
    return json.loads(path.read_text(encoding="utf-8"))


def _topological_order(contracts):
    """Return contracts in dependency order; raise on missing deps or cycles."""
    by_name = {}
    for cp in contracts:
        c = _load_contract(cp)
        name = c["name"]
        if name in by_name:
            raise ValueError("duplicate component name: %s" % name)
        by_name[name] = (cp, c)

    # Map output path -> producing component name.
    producer = {}
    for name, (cp, c) in by_name.items():
        out = c["output"]
        if out in producer:
            raise ValueError("duplicate output path: %s" % out)
        producer[out] = name

    # Build dependency edges: component depends on components producing its inputs.
    deps = {}
    for name, (cp, c) in by_name.items():
        d = set()
        for inp in c["inputs"]:
            if inp in producer:
                d.add(producer[inp])
            else:
                # Input not produced by any component must already exist as a file.
                if not (ROOT / inp).is_file():
                    raise ValueError("missing input: %s" % inp)
        deps[name] = d

    # Kahn's algorithm.
    order = []
    remaining = set(by_name)
    while remaining:
        ready = [n for n in remaining if deps[n] <= set(order)]
        if not ready:
            raise ValueError("dependency cycle detected")
        ready.sort()
        for n in ready:
            order.append(n)
            remaining.discard(n)

    return [by_name[n] for n in order]


def main():
    contracts = [
        x
        for x in ROOT.rglob("contract.json")
        if "outputs" not in x.relative_to(ROOT).parts
    ]
    if not contracts:
        raise ValueError("no contracts")

    ordered = _topological_order(contracts)

    for cp, c in ordered:
        render = cp.with_name("render.py")
        if not render.is_file():
            raise ValueError("missing render.py for %s" % c["name"])
        subprocess.run(
            [sys.executable, str(render)],
            cwd=ROOT,
            check=True,
            timeout=180,
        )

    # Run the integrator to produce core_manifest.json.
    integrate = ROOT / "integrate.py"
    subprocess.run(
        [sys.executable, str(integrate)],
        cwd=ROOT,
        check=True,
        timeout=180,
    )

    # Run the final report generator.
    final_report = ROOT / "final_report.py"
    subprocess.run(
        [sys.executable, str(final_report)],
        cwd=ROOT,
        check=True,
        timeout=180,
    )


if __name__ == "__main__":
    main()

import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

TITLE = "每日晚餐提醒的去重、冲突取消与通知"


def _load_core():
    path = ROOT / "outputs" / "core_manifest.json"
    return json.loads(path.read_text(encoding="utf-8"))


def _sha256(core):
    text = json.dumps(
        core,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")
    return hashlib.sha256(text).hexdigest()


def _attention(components):
    names = []
    for name, result in components.items():
        if not isinstance(result, dict):
            continue
        if result.get("blocked") is True:
            names.append(name)
            continue
        for key in ("complete", "checkout", "committed", "ok"):
            if result.get(key) is False:
                names.append(name)
                break
        else:
            for key in ("unavailable", "missing", "conflicts", "unreachable"):
                v = result.get(key)
                if isinstance(v, (list, dict, str)) and v:
                    names.append(name)
                    break
    return sorted(set(names))


def build_report(core):
    components = core["components"]
    return {
        "title": TITLE,
        "component_count": len(components),
        "sha256": _sha256(core),
        "attention": _attention(components),
    }


def main():
    core = _load_core()
    report = build_report(core)
    out = ROOT / "outputs" / "final_report.json"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(
        json.dumps(report, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False)
        + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()

import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))

import final_report


class TestFinalReport(unittest.TestCase):
    def test_build_report_shape_and_values(self):
        core = {
            "components": {
                "a": {"blocked": True},
                "b": {"complete": False},
                "c": {"ok": True, "unavailable": []},
                "d": {"missing": ["x"]},
                "e": {"ok": True},
            }
        }
        report = final_report.build_report(core)
        self.assertEqual(
            set(report), {"title", "component_count", "sha256", "attention"}
        )
        self.assertEqual(report["title"], final_report.TITLE)
        self.assertEqual(report["component_count"], 5)
        self.assertEqual(len(report["sha256"]), 64)
        # attention: a (blocked), b (complete False), d (missing non-empty)
        self.assertEqual(report["attention"], ["a", "b", "d"])

    def test_sha256_matches_spec(self):
        import hashlib

        core = {"components": {"z": {"ok": True}}}
        expected_text = json.dumps(
            core,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        self.assertEqual(
            final_report._sha256(core), hashlib.sha256(expected_text).hexdigest()
        )

    def test_attention_false_vs_zero(self):
        core = {
            "components": {
                "a": {"ok": 0},
                "b": {"ok": False},
                "c": {"unavailable": 0},
                "d": {"unavailable": []},
                "e": {"unavailable": None},
            }
        }
        report = final_report.build_report(core)
        # only b triggers (ok explicitly False); 0/[]/None do not.
        self.assertEqual(report["attention"], ["b"])


if __name__ == "__main__":
    unittest.main()

