import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(ROOT))

import final_report


class TestFinalReport(unittest.TestCase):
    def test_build_report_shape_and_values(self):
        core = {
            "components": {
                "a": {"blocked": True},
                "b": {"complete": False},
                "c": {"ok": True, "unavailable": []},
                "d": {"missing": ["x"]},
                "e": {"ok": True},
            }
        }
        report = final_report.build_report(core)
        self.assertEqual(
            set(report), {"title", "component_count", "sha256", "attention"}
        )
        self.assertEqual(report["title"], final_report.TITLE)
        self.assertEqual(report["component_count"], 5)
        self.assertEqual(len(report["sha256"]), 64)
        # attention: a (blocked), b (complete False), d (missing non-empty)
        self.assertEqual(report["attention"], ["a", "b", "d"])

    def test_sha256_matches_spec(self):
        import hashlib

        core = {"components": {"z": {"ok": True}}}
        expected_text = json.dumps(
            core,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
            allow_nan=False,
        ).encode("utf-8")
        self.assertEqual(
            final_report._sha256(core), hashlib.sha256(expected_text).hexdigest()
        )

    def test_attention_false_vs_zero(self):
        core = {
            "components": {
                "a": {"ok": 0},
                "b": {"ok": False},
                "c": {"unavailable": 0},
                "d": {"unavailable": []},
                "e": {"unavailable": None},
            }
        }
        report = final_report.build_report(core)
        # only b triggers (ok explicitly False); 0/[]/None do not.
        self.assertEqual(report["attention"], ["b"])


if __name__ == "__main__":
    unittest.main()

